<?php require __DIR__.'/includes/header.php';$id=(int)($_GET['id']??0);$st=db()->prepare('SELECT r.*,c.name_en company_name FROM update_requests r JOIN companies c ON c.id=r.company_id WHERE r.id=?');$st->execute([$id]);$r=$st->fetch();if(!$r||(!isAdmin()&&$r['company_id']!=$_SESSION['user']['company_id']))exit('Not found');checkCsrf();if(isAdmin()&&$_SERVER['REQUEST_METHOD']==='POST'&&in_array($_POST['action'],['approved','rejected','processing'])){$status=$_POST['action'];db()->prepare('UPDATE update_requests SET status=?,reviewed_by=?,reviewed_at=NOW(),review_note=? WHERE id=?')->execute([$status,$_SESSION['user']['id'],$_POST['note']??'',$id]);if($status==='approved'){ $new=json_decode($r['new_data'],true)?:[]; if($r['type']==='company'){$set=[];$vals=[];foreach($new as $k=>$v){$set[]="$k=?";$vals[]=$v;}$vals[]=$r['company_id'];db()->prepare('UPDATE companies SET '.implode(',',$set).' WHERE id=?')->execute($vals);} elseif($r['type']==='worker_create'){db()->prepare('INSERT INTO workers(company_id,name_ar,name_en,civil_id,phone,email,nationality,job_ar,job_en,work_hours) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$r['company_id'],$new['name_ar'],$new['name_en'],$new['civil_id'],$new['phone'],$new['email'],$new['nationality'],$new['job_ar'],$new['job_en'],$new['work_hours']]);} elseif($r['type']==='project_create'){db()->prepare('INSERT INTO projects(company_id,name_ar,name_en,start_date,end_date,location,housing_allowance,status) VALUES(?,?,?,?,?,?,?,?)')->execute([$r['company_id'],$new['name_ar'],$new['name_en'],$new['start_date'],$new['end_date'],$new['location'],$new['housing_allowance'],$new['status']]);}}audit('review_request','update_request',$id,['status'=>$status]);header('Location:request-view.php?id='.$id);exit;}?><div class="title-row"><h1><?=t('requests')?> #<?=$id?></h1><span class="badge <?=$r['status']?>"><?=t($r['status'])?></span></div><div class="grid two"><section class="card"><h3>Current / Old Data</h3><pre><?=e(json_encode(json_decode($r['old_data'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></section><section class="card"><h3>Requested Data</h3><pre><?=e(json_encode(json_decode($r['new_data'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></section></div><?php if(isAdmin()&&$r['status']!=='approved'):?><section class="card"><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><textarea name="note" placeholder="Review note"></textarea><div class="actions"><button name="action" value="approved" class="btn success">✓ <?=t('approve')?></button><button name="action" value="processing" class="btn warning">⏳ <?=t('processing')?></button><button name="action" value="rejected" class="btn danger">✕ <?=t('reject')?></button></div></form></section><?php endif;?><?php require __DIR__.'/includes/footer.php';?>
